const SUBJECTS=[
['Mathematics','MTH','Quantitative reasoning, modelling and problem solving'],['English Language','ENG','Communication, comprehension and composition'],['Kiswahili','KIS','Mawasiliano, sarufi, fasihi na matumizi'],['Biology','BIO','Living systems, health and scientific inquiry'],['Chemistry','CHE','Matter, reactions and laboratory competence'],['Physics','PHY','Measurement, forces, energy and practical inquiry'],['Geography','GEO','People, environment, maps and spatial reasoning'],['History','HIS','Historical evidence, societies and change'],['Civics','CIV','Citizenship, governance and social responsibility'],['Computer Science','CSC','Computational thinking and digital creation'],['Agriculture','AGR','Sustainable production and agricultural enterprise'],['Business Studies','BUS','Enterprise, markets and business decision making'],['Commerce','COM','Trade, finance and commercial practice'],['Bookkeeping','BKP','Accounting records and financial literacy'],['Economics','ECO','Resources, markets and economic reasoning'],['Literature in English','LIT','Literary analysis, interpretation and expression'],['French','FRE','Functional language and intercultural communication'],['Arabic','ARB','Language competence and communication'],['Fine Art','ART','Creative expression, design and visual literacy'],['Music','MUS','Performance, theory and creative composition'],['Physical Education','PED','Movement competence, fitness and wellbeing'],['Food & Nutrition','FNT','Nutrition, food science and practical preparation'],['Home Economics','HEC','Household management, textiles and wellbeing'],['Religious Studies','RLS','Ethics, beliefs and social understanding'],['General Studies','GST','A-level interdisciplinary reasoning and citizenship'],['Advanced Mathematics','AMT','A-level mathematical reasoning and applications'],['ICT','ICT','Information systems, productivity and digital literacy']
];
const TOPICS={BIO:['Introduction to Biology','Cell Structure and Organisation','Nutrition','Transport of Materials','Respiration','Coordination','Reproduction','Genetics and Evolution','Ecology and Environment'],MTH:['Numbers and Operations','Algebra','Geometry','Measurement','Statistics','Probability','Functions','Trigonometry'],ENG:['Listening and Speaking','Reading Comprehension','Grammar in Context','Vocabulary Development','Writing Skills','Oral Communication','Literature Response'],PHY:['Measurement','Force and Motion','Pressure','Work Energy and Power','Heat','Waves','Electricity','Magnetism'],CHE:['Laboratory Techniques','Matter','Atomic Structure','Periodic Classification','Chemical Bonding','Acids Bases and Salts','Organic Chemistry'],GEO:['Map Reading','Weather and Climate','Earth Structure','Population','Agriculture','Industry','Transport','Environmental Management']};
const state={role:localStorage.getItem('tesea_role')||'learner',page:localStorage.getItem('tesea_page')||'dashboard',theme:localStorage.getItem('tesea_theme')||'light',subject:'BIO',topic:5,lessonMode:'text',quizAnswers:{},progress:JSON.parse(localStorage.getItem('tesea_progress')||'{"BIO":58,"MTH":42,"ENG":71,"CHE":36,"PHY":48,"GEO":62}')};
const nav={learner:[['Learning',['dashboard','My learning'],['subjects','Subjects'],['path','Learning path'],['lesson','Current lesson'],['assessments','Assessments'],['progress','Progress']],['Support',['rafiki','Rafiki AI'],['announcements','Announcements'],['subscription','Subscription']]],tutor:[['Teaching',['dashboard','Dashboard'],['classes','Classes'],['content','Content studio'],['assessments','Assessment studio'],['live','Live lessons']],['Insights',['learner-insights','Learner insights'],['question-bank','Question bank'],['announcements','Announcements']]],admin:[['Platform',['dashboard','Dashboard'],['curriculum','Curriculum studio'],['users','Users & roles'],['subscriptions','Subscriptions'],['question-bank','Question bank']],['Operations',['announcements','Announcements'],['content-governance','Content governance'],['analytics','Analytics'],['settings','Platform settings']]],crm:[['CRM',['dashboard','Pipeline'],['leads','Leads'],['schools','Schools'],['campaigns','Campaigns'],['support','Support cases']],['Revenue',['subscriptions','Subscription ops'],['reports','Reports']]]};
function save(){localStorage.setItem('tesea_role',state.role);localStorage.setItem('tesea_page',state.page);localStorage.setItem('tesea_theme',state.theme);localStorage.setItem('tesea_progress',JSON.stringify(state.progress));}
function app(){document.documentElement.dataset.theme=state.theme;document.querySelector('#app').innerHTML=state.page==='landing'?landing():shell();bind();}
function shell(){const groups=nav[state.role];return `<div class="app-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu">☰</button><div class="brand"><img src="assets/tesea-logo.png" alt="TESEA Academy"></div><div class="search"><input id="globalSearch" placeholder="Search subjects, lessons, learners, questions…"></div><div class="top-actions"><button class="icon-btn" data-action="theme">${state.theme==='light'?'☾':'☀'}</button><button class="icon-btn" data-nav="announcements">◉</button><button class="role-switch" data-action="roles">${roleName(state.role)} ▾</button></div></header><div class="layout"><aside class="sidebar" id="sidebar"><div class="workspace"><small>Workspace</small><strong>${roleName(state.role)}</strong></div>${groups.map(g=>`<div class="nav-group"><div class="nav-title">${g[0]}</div>${g.slice(1).map(x=>`<button class="nav-item ${state.page===x[0]?'active':''}" data-nav="${x[0]}">${icon(x[0])}<span>${x[1]}</span>${x[0]==='announcements'?'<span class="count">3</span>':''}</button>`).join('')}</div>`).join('')}<div class="nav-group"><div class="nav-title">Switch</div><button class="nav-item" data-nav="landing">⌂<span>Public website</span></button></div></aside><main class="main">${renderPage()}</main></div></div>`}
function landing(){return `<div class="landing"><nav class="landing-nav"><img src="assets/tesea-logo.png"><div class="links"><a href="#model">Learning model</a><a href="#subjects">Subjects</a><a href="#access">Access</a></div><button class="btn" data-action="theme">Theme</button><button class="btn primary" data-action="enter">Open platform</button></nav><section class="hero"><div><span class="badge">NECTA competence-based learning</span><h1>Learn for competence, not completion.</h1><p>TESEA Academy gives Form 1–6 learners a focused path from diagnostic baseline to concept learning, guided practice, assessment, feedback, mastery and exam readiness.</p><div class="actions" style="margin-top:22px"><button class="btn primary" data-action="enter">Start learning</button><button class="btn" data-action="role-demo">Explore workspaces</button></div></div><div class="hero-card"><div class="eyebrow">TESEA learning path</div><div class="hero-path">${['Diagnose prior knowledge','Learn concept and competency','Practice with feedback','Apply through assignment','Check mastery','Relearn gaps','Demonstrate competence'].map((x,i)=>`<div class="hero-step"><span>${i+1}</span><div><strong>${x}</strong><div class="muted">Evidence is captured in the learner mastery profile.</div></div></div>`).join('')}</div></div></section><section class="feature-wrap" id="model"><h2>A quieter learning interface with a clear next action.</h2><div class="grid">${[['27-subject curriculum','Form 1–6 course structures with topic, sub-topic, outcomes and evidence.'],['Multi-format lessons','Interactive text, video, audio, PDF, shorts and live learning.'],['Rafiki AI engine','Question-bank generation, guided explanation and gap-based practice.'],['Competence tracking','Progress separates content completion from demonstrated mastery.'],['Tutor workflow','Create, assign, review, intervene and run live lessons.'],['Admin + CRM','Curriculum, subscriptions, users, announcements, leads and support.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section></div>`}
function renderPage(){if(state.page==='landing') return landing();const r=state.role,p=state.page;if(r==='learner')return learnerPage(p);if(r==='tutor')return tutorPage(p);if(r==='admin')return adminPage(p);return crmPage(p)}
function learnerPage(p){if(p==='dashboard')return learnerDashboard();if(p==='subjects')return subjectsPage();if(p==='path')return learningPath();if(p==='lesson')return lessonPage();if(p==='assessments')return assessmentsPage();if(p==='progress')return progressPage();if(p==='rafiki')return rafikiPage();if(p==='announcements')return announcementsPage();if(p==='subscription')return subscriptionPage();return learnerDashboard()}
function head(e,t,d,a=''){return `<div class="page-head"><div><div class="eyebrow">${e}</div><h1>${t}</h1><p>${d}</p></div><div class="actions">${a}</div></div>`}
function learnerDashboard(){return head('Learner workspace','Good evening, Amani','Your next action is chosen from competency evidence, not from a crowded content feed.',`<button class="btn" data-nav="progress">View progress</button><button class="btn primary" data-nav="lesson">Continue Biology</button>`)+`<div class="card" style="border-left:4px solid var(--b)"><div class="grid2"><div><span class="badge">Next best action</span><h2 style="margin:9px 0 5px">Complete the Coordination mastery checkpoint</h2><p>Your lesson completion is 72%, but demonstrated mastery is 58%. Finish the reflex arc practice before moving to endocrine coordination.</p><div class="actions" style="margin-top:14px"><button class="btn primary" data-nav="assessments">Start checkpoint</button><button class="btn" data-nav="lesson">Review lesson</button></div></div><div><div class="progress"><span style="width:58%"></span></div><div class="progress-meta"><span>Competency mastery</span><strong>58%</strong></div></div></div></div><div class="section"><div class="kpis"><div class="kpi"><strong>64%</strong><span>Overall mastery</span></div><div class="kpi"><strong>18</strong><span>Competencies demonstrated</span></div><div class="kpi"><strong>5</strong><span>Competencies to reinforce</span></div><div class="kpi"><strong>7</strong><span>Day learning streak</span></div></div></div><div class="section grid2"><div><div class="section-head"><div><h2>Continue learning</h2><p>Priority subjects based on current mastery evidence.</p></div><button class="btn sm" data-nav="subjects">All subjects</button></div><div class="grid">${['BIO','MTH','ENG'].map(code=>subjectMini(code)).join('')}</div></div><div><div class="section-head"><div><h2>Today</h2><p>Focused learning sequence.</p></div></div><div class="card list"><div class="list-row"><span class="badge">1</span><div class="grow"><strong>Interactive lesson</strong><small>Biology • Coordination</small></div><span>18 min</span></div><div class="list-row"><span class="badge">2</span><div class="grow"><strong>Guided practice</strong><small>5 questions with feedback</small></div><span>10 min</span></div><div class="list-row"><span class="badge">3</span><div class="grow"><strong>Mastery check</strong><small>Score ≥ 70% to advance</small></div><span>12 min</span></div></div></div></div><div class="section"><div class="section-head"><div><h2>Announcements</h2><p>Only relevant academic and account updates.</p></div><button class="btn sm" data-nav="announcements">View all</button></div>${announcementCards(2)}</div>`}
function subjectMini(code){const s=SUBJECTS.find(x=>x[1]===code),pr=state.progress[code]||25;return `<div class="card click" data-subject="${code}"><div class="subject-icon">${code}</div><h3>${s[0]}</h3><p>${s[2]}</p><div class="progress" style="margin-top:14px"><span style="width:${pr}%"></span></div><div class="progress-meta"><span>Mastery</span><strong>${pr}%</strong></div></div>`}
function subjectsPage(){return head('Curriculum','27 NECTA competence subjects','Browse by subject. Each course is organised around competencies, learning outcomes, evidence and mastery checkpoints.',`<select id="formFilter" class="btn"><option>Form 1</option><option>Form 2</option><option selected>Form 3</option><option>Form 4</option><option>Form 5</option><option>Form 6</option></select>`)+`<div class="subject-grid">${SUBJECTS.map((s,i)=>`<div class="subject-card" data-subject="${s[1]}"><div class="subject-icon">${s[1]}</div><h3>${s[0]}</h3><p>${s[2]}</p><div class="progress"><span style="width:${state.progress[s[1]]||Math.max(8,52-i)}%"></span></div><div class="progress-meta"><span>Mastery</span><span>${state.progress[s[1]]||Math.max(8,52-i)}%</span></div></div>`).join('')}</div>`}
function coursePage(){const s=SUBJECTS.find(x=>x[1]===state.subject)||SUBJECTS[3],topics=TOPICS[state.subject]||['Foundations','Core concepts','Applied knowledge','Practical work','Project and inquiry','Revision and assessment'];return head('Course overview',`Form 3 ${s[0]}`,s[2],`<button class="btn" data-nav="subjects">Back to subjects</button><button class="btn primary" data-nav="path">Open learning path</button>`)+`<div class="grid2"><div><div class="card"><span class="badge">Course overview</span><h2>Purpose</h2><p>This course develops knowledge, skills, values and application through short learning cycles: concept → practice → evidence → feedback → mastery.</p><h3 style="margin-top:20px">Learning outcomes</h3><ul><li>Explain core concepts using appropriate subject language.</li><li>Apply knowledge to familiar and unfamiliar situations.</li><li>Use evidence, procedures and reasoning to solve problems.</li><li>Demonstrate competence through assignments, practical tasks and assessments.</li></ul></div><div class="section"><div class="section-head"><div><h2>Topics and sub-topics</h2><p>Each topic unlocks after the required prerequisite evidence.</p></div></div><div class="list">${topics.map((t,i)=>`<div class="card click" data-topic="${i}"><div class="list-row"><span class="step-dot ${i<state.topic?'done':i===state.topic?'current':''}">${i<state.topic?'✓':i+1}</span><div class="grow"><strong>${t}</strong><small>${['Concept introduction','Guided worked examples','Interactive practice','Assignment / practical evidence','Mastery checkpoint'].slice(0,3+(i%3)).join(' • ')}</small></div><span class="badge ${i<state.topic?'ok':i===state.topic?'':'neutral'}">${i<state.topic?'Mastered':i===state.topic?'In progress':'Locked'}</span></div></div>`).join('')}</div></div></div><div><div class="card"><h3>Course progress</h3><div style="font-size:40px;font-weight:850">${state.progress[state.subject]||36}%</div><div class="progress"><span style="width:${state.progress[state.subject]||36}%"></span></div><div class="progress-meta"><span>Demonstrated mastery</span><span>Target 80%</span></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Evidence mix</h3><div class="list"><div class="list-row"><div class="grow"><strong>Lesson checks</strong><small>Continuous</small></div><span>20%</span></div><div class="list-row"><div class="grow"><strong>Assignments / practical</strong><small>Applied competence</small></div><span>30%</span></div><div class="list-row"><div class="grow"><strong>Tests and exams</strong><small>Independent demonstration</small></div><span>50%</span></div></div></div></div></div>`}
function learningPath(){return head('Competence pathway','TESEA learning path','A learner advances when evidence shows sufficient competence. Completion alone does not unlock mastery.',`<button class="btn primary" data-nav="lesson">Continue current step</button>`)+`<div class="grid2"><div class="card"><div class="path">${[['Baseline diagnostic','Identify prior knowledge and misconceptions','done'],['Concept learning','Interactive text + video explanation','done'],['Guided practice','Hints, worked examples and immediate feedback','done'],['Application task','Assignment / practical evidence','current'],['Mastery checkpoint','Independent quiz or topic test',''],['Targeted relearning','Rafiki AI remediates weak outcomes',''],['Competency demonstrated','Progress recorded and next topic unlocked','']].map((x,i)=>`<div class="path-step"><div class="step-dot ${x[2]}">${x[2]==='done'?'✓':i+1}</div><div><strong>${x[0]}</strong><div class="muted">${x[1]}</div></div><span class="badge ${x[2]==='done'?'ok':x[2]==='current'?'':'neutral'}">${x[2]==='done'?'Complete':x[2]==='current'?'Current':'Upcoming'}</span></div>`).join('')}</div></div><div class="card"><h3>Mastery rules</h3><p>TESEA separates learning activity from competence evidence.</p><div class="list" style="margin-top:12px"><div class="list-row"><div class="grow"><strong>Green ≥ 80%</strong><small>Competency demonstrated</small></div></div><div class="list-row"><div class="grow"><strong>Amber 60–79%</strong><small>Reinforce before progression</small></div></div><div class="list-row"><div class="grow"><strong>Red &lt; 60%</strong><small>Targeted relearning required</small></div></div></div><button class="btn soft" data-nav="rafiki" style="width:100%;margin-top:14px">Ask Rafiki to explain my gaps</button></div></div>`}
function lessonPage(){const modes=[['text','Interactive text'],['video','Video'],['audio','Audio'],['pdf','PDF notes'],['shorts','Shorts'],['live','Live lesson']];return head('Biology • Coordination','Reflex action and the nervous system','Outcome: explain the reflex arc and relate each structure to fast protective response.',`<button class="btn" data-nav="path">Learning path</button><button class="btn primary" data-nav="assessments">Practice</button>`)+`<div class="tabs">${modes.map(m=>`<button class="tab ${state.lessonMode===m[0]?'active':''}" data-mode="${m[0]}">${m[1]}</button>`).join('')}</div>${lessonModeContent()}`}
function lessonModeContent(){const side=`<aside class="lesson-aside"><div class="card"><h3>Lesson progress</h3><div class="progress"><span style="width:72%"></span></div><div class="progress-meta"><span>Completed</span><strong>72%</strong></div></div><div class="card"><h3>Learning outcomes</h3><div class="list"><div class="list-row"><span class="badge ok">✓</span><div class="grow">Define stimulus, receptor and response</div></div><div class="list-row"><span class="badge">2</span><div class="grow">Trace a reflex arc correctly</div></div><div class="list-row"><span class="badge neutral">3</span><div class="grow">Apply the concept to exam scenarios</div></div></div></div><div class="card"><h3>Next evidence</h3><p>5-question guided practice.</p><button class="btn primary" data-nav="assessments" style="width:100%;margin-top:12px">Start practice</button></div></aside>`;if(state.lessonMode==='video')return `<div class="lesson-shell"><div><div class="media-stage"><button class="play" data-action="play">▶</button><div style="position:absolute;left:20px;bottom:18px"><strong>Reflex arc explained</strong><div style="opacity:.75">08:42 • English + Kiswahili captions</div></div></div><div class="card" style="margin-top:14px"><h3>Chapters</h3>${['Stimulus and receptor','Sensory neurone','Relay neurone','Motor neurone and effector'].map((x,i)=>`<div class="list-row"><span>${i+1}</span><div class="grow"><strong>${x}</strong></div><span>${['00:00','02:10','04:18','06:24'][i]}</span></div>`).join('')}</div></div>${side}</div>`;if(state.lessonMode==='audio')return `<div class="lesson-shell"><div><div class="audio-stage"><span class="badge" style="background:#fff;color:#111">Audio lesson</span><h1>Reflex action: listen and recall</h1><p style="color:#f1dce3">12 min • downloadable for offline learning</p><div class="wave">${Array.from({length:70},(_,i)=>`<i style="height:${18+(i*17)%62}px"></i>`).join('')}</div><button class="btn" data-action="play">▶ Play / pause</button></div><div class="card" style="margin-top:14px"><h3>Audio checkpoints</h3>${['Pause and define stimulus','Trace the impulse aloud','Explain why reflexes are fast'].map((x,i)=>`<div class="list-row"><span class="badge">${i+1}</span><div class="grow"><strong>${x}</strong></div></div>`).join('')}</div></div>${side}</div>`;if(state.lessonMode==='pdf')return `<div class="lesson-shell"><div class="pdf-stage"><div class="paper"><div class="eyebrow">TESEA Biology Notes</div><h1>Coordination: Reflex Action</h1><p><strong>Learning outcome:</strong> Explain the pathway of a reflex arc and the role of each structure.</p><h2>Core notes</h2><p>A reflex action is a rapid, automatic response to a stimulus. It protects the body by using a short neural pathway before conscious interpretation.</p><ol><li>A receptor detects a stimulus.</li><li>A sensory neurone carries an impulse to the spinal cord.</li><li>A relay neurone transfers the impulse.</li><li>A motor neurone carries the impulse to an effector.</li><li>The effector produces a response.</li></ol><h2>Competence check</h2><p>Can you explain the pathway without looking at the diagram?</p></div></div>${side}</div>`;if(state.lessonMode==='shorts')return `<div class="lesson-shell"><div class="short-stage"><div><span class="badge" style="background:white;color:#111">01 / 06</span><h1>Reflex arc in 60 seconds</h1><p style="color:#eee">Receptor → sensory neurone → relay neurone → motor neurone → effector.</p><button class="btn" data-action="short-next">Next short</button></div></div>${side}</div>`;if(state.lessonMode==='live')return `<div class="lesson-shell"><div><div class="live-stage"><div style="text-align:center"><div style="width:84px;height:84px;border-radius:50%;background:var(--b);display:grid;place-items:center;margin:auto;font-weight:900;font-size:28px">TM</div><h2>Live Biology Revision</h2><p style="color:#ddd">Tutor Thomas • 34 learners joined</p><span class="badge bad">● LIVE</span><div class="actions" style="justify-content:center;margin-top:18px"><button class="btn" data-action="mic">🎙 Mic</button><button class="btn" data-action="hand">✋ Raise hand</button><button class="btn danger" data-action="leave-live">Leave</button></div></div></div><div class="card" style="margin-top:14px"><h3>Live agenda</h3><div class="list-row"><span class="badge ok">Done</span><div class="grow"><strong>Reflex arc recap</strong></div></div><div class="list-row"><span class="badge">Now</span><div class="grow"><strong>Worked exam examples</strong></div></div><div class="list-row"><span class="badge neutral">Next</span><div class="grow"><strong>Student questions + quiz</strong></div></div></div></div>${side}</div>`;return `<div class="lesson-shell"><article class="lesson-reader"><span class="badge">Interactive text lesson</span><h1>How a reflex action protects the body</h1><p>Imagine touching a hot surface. Your hand moves away before you consciously decide to move it. This is possible because the nervous system uses a short, fast pathway called a <strong>reflex arc</strong>.</p><h2>1. From stimulus to receptor</h2><p>A stimulus is a detectable change in the internal or external environment. Receptors are specialised cells or organs that detect a specific type of stimulus.</p><div class="callout"><strong>Think before continuing.</strong><br>Why is speed more important than conscious decision-making when touching a hot object?</div><h2>2. The reflex arc</h2><ol><li>The receptor detects the stimulus.</li><li>The sensory neurone carries an impulse into the spinal cord.</li><li>A relay neurone transfers the impulse inside the central nervous system.</li><li>The motor neurone carries the impulse to an effector.</li><li>The effector contracts or secretes, producing a response.</li></ol><h2>3. Apply the idea</h2><p>In an exam response, do not merely list the structures. Explain the direction of impulse transmission and link the pathway to the rapid protective response.</p><div class="callout"><strong>Quick check:</strong> Put these in order: effector, sensory neurone, receptor, motor neurone, relay neurone.</div><div class="actions"><button class="btn" data-action="save-note">Save note</button><button class="btn primary" data-nav="assessments">Check understanding</button></div></article>${side}</div>`}
function assessmentsPage(){const qs=[['Which sequence correctly represents a reflex arc?',['Receptor → sensory → relay → motor → effector','Receptor → motor → sensory → effector','Effector → motor → relay → sensory','Sensory → receptor → motor → effector'],0],['Why is a reflex action usually rapid?',['It always involves the brain first','It uses a short neural pathway and automatic response','Motor neurones carry impulses faster than all neurones','Receptors directly contract muscles'],1],['Which structure detects the stimulus?',['Effector','Relay neurone','Receptor','Motor neurone'],2]];return head('Assessment centre','Practice, assignments, tests and exams','Assessment evidence is mapped to learning outcomes and used to decide whether to advance, reinforce or relearn.',`<button class="btn" data-action="assessment-history">History</button><button class="btn primary" data-action="submit-quiz">Submit practice</button>`)+`<div class="grid2"><div><div class="tabs"><button class="tab active">Guided practice</button><button class="tab">Assignments</button><button class="tab">Topic tests</button><button class="tab">Exams</button></div><div class="list">${qs.map((q,qi)=>`<div class="question"><div class="eyebrow">Question ${qi+1} • Outcome ${qi+1}</div><h3>${q[0]}</h3>${q[1].map((o,oi)=>`<div class="option ${state.quizAnswers[qi]===oi?'selected':''}" data-answer="${qi}:${oi}"><span>${String.fromCharCode(65+oi)}.</span><span>${o}</span></div>`).join('')}</div>`).join('')}</div></div><div><div class="card"><h3>Assessment map</h3><div class="list"><div class="list-row"><div class="grow"><strong>Concept recall</strong><small>2 questions</small></div><span class="badge ok">Ready</span></div><div class="list-row"><div class="grow"><strong>Sequence reasoning</strong><small>1 question</small></div><span class="badge">Current</span></div><div class="list-row"><div class="grow"><strong>Application scenario</strong><small>Unlocks next</small></div><span class="badge neutral">Next</span></div></div></div><div class="card" style="margin-top:12px"><h3>Mastery rule</h3><p>70% unlocks the next learning activity. 80%+ marks the competency as demonstrated after independent evidence.</p></div></div></div>`}
function progressPage(){return head('Learning analytics','Progress and competence profile','See the difference between activity completion, assessment performance and demonstrated competence.')+`<div class="kpis"><div class="kpi"><strong>64%</strong><span>Overall mastery</span></div><div class="kpi"><strong>77%</strong><span>Lesson completion</span></div><div class="kpi"><strong>68%</strong><span>Assessment average</span></div><div class="kpi"><strong>18/27</strong><span>Competencies demonstrated</span></div></div><div class="section grid2"><div class="card"><h3>Subject mastery</h3>${['BIO','MTH','ENG','CHE','PHY','GEO'].map(c=>{let s=SUBJECTS.find(x=>x[1]===c),v=state.progress[c];return `<div style="margin-top:16px"><div class="progress-meta"><strong>${s[0]}</strong><span>${v}%</span></div><div class="progress"><span style="width:${v}%"></span></div></div>`}).join('')}</div><div class="card"><h3>Competency gaps</h3><div class="list"><div class="list-row"><span class="badge bad">Priority</span><div class="grow"><strong>Chemistry: balancing equations</strong><small>48% evidence score</small></div></div><div class="list-row"><span class="badge warn">Reinforce</span><div class="grow"><strong>Mathematics: linear equations</strong><small>63% evidence score</small></div></div><div class="list-row"><span class="badge warn">Reinforce</span><div class="grow"><strong>Physics: pressure calculations</strong><small>66% evidence score</small></div></div></div><button class="btn soft" data-nav="rafiki" style="width:100%;margin-top:12px">Generate gap practice with Rafiki</button></div></div>`}
function rafikiPage(){return head('Rafiki AI Engine','Study with evidence, not random prompts','Rafiki uses your selected subject, learning outcome and current mastery gap to generate explanations and practice.',`<button class="btn" data-action="rafiki-history">Study history</button>`)+`<div class="grid2"><div class="card"><div class="form-grid"><div class="field"><label>Subject</label><select id="rafikiSubject"><option>Biology</option><option>Mathematics</option><option>Chemistry</option></select></div><div class="field"><label>Mode</label><select id="rafikiMode"><option>Explain a gap</option><option>Generate practice</option><option>Worked example</option><option>Exam feedback</option></select></div><div class="field full"><label>What do you need help with?</label><textarea id="rafikiPrompt" rows="6">Explain why a reflex action is faster than a conscious response, then test me with three questions.</textarea></div></div><button class="btn primary" data-action="rafiki-send" style="margin-top:12px">Ask Rafiki</button><div id="rafikiReply" class="callout" style="display:none;margin-top:16px"></div></div><div class="card"><h3>AI learning guardrails</h3><p>Rafiki should support thinking rather than replace it.</p><div class="list" style="margin-top:12px"><div class="list-row"><span class="badge ok">1</span><div class="grow"><strong>Outcome-aware</strong><small>Questions map to the active competency.</small></div></div><div class="list-row"><span class="badge ok">2</span><div class="grow"><strong>Hint before answer</strong><small>Encourages retrieval and reasoning.</small></div></div><div class="list-row"><span class="badge ok">3</span><div class="grow"><strong>Evidence recorded</strong><small>Practice informs recommendations, not formal grades.</small></div></div></div></div></div>`}
function announcementCards(n=4){const data=[['Academic','Form 3 Biology live revision tonight at 19:00 EAT.'],['Assessment','Mathematics Topic Test 4 opens tomorrow and closes Friday.'],['Platform','New offline PDF notes are available for Chemistry and Physics.'],['Account','Your annual TESEA Plus plan is active until 17 Aug 2027.']];return `<div class="list">${data.slice(0,n).map((x,i)=>`<div class="announcement"><div class="ann-dot"></div><div class="grow"><span class="badge ${i===1?'warn':''}">${x[0]}</span><strong style="display:block;margin:6px 0 2px">${x[1]}</strong><small class="muted">${i+1} ${i?'days':'hours'} ago</small></div><button class="btn sm" data-action="mark-read">Mark read</button></div>`).join('')}</div>`}
function announcementsPage(){return head('Communication','Announcements','A low-noise in-app announcement engine for academic, operational, subscription and live-session updates.',`<button class="btn" data-action="mark-all">Mark all read</button>`)+announcementCards(4)}
