function platformSettings(){return head('Configuration','Platform settings','Manage learning defaults, mastery thresholds, theme, localisation, integrations and security.',`<button class="btn primary" data-action="save-settings">Save changes</button>`)+`<div class="grid2"><div class="card"><h3>Learning rules</h3><div class="form-grid"><div class="field"><label>Progression threshold</label><input value="70%"></div><div class="field"><label>Competency mastery threshold</label><input value="80%"></div><div class="field"><label>Default language</label><select><option>English</option><option>Kiswahili</option></select></div><div class="field"><label>Academic framework</label><select><option>NECTA CBL</option></select></div></div></div><div class="card"><h3>Integrations</h3><div class="list"><div class="list-row"><div class="grow"><strong>Payment gateway</strong><small>Production credential required</small></div><span class="badge warn">Configure</span></div><div class="list-row"><div class="grow"><strong>Live lesson provider</strong><small>Video SDK / provider</small></div><span class="badge warn">Configure</span></div><div class="list-row"><div class="grow"><strong>Rafiki AI service</strong><small>Question generation and tutoring</small></div><span class="badge ok">Prototype</span></div></div></div></div>`}
function crmPage(p){if(p==='dashboard')return crmDashboard();if(p==='leads')return crmLeads();if(p==='schools')return crmSchools();if(p==='campaigns')return crmCampaigns();if(p==='support')return crmSupport();if(p==='subscriptions')return adminSubscriptions();if(p==='reports')return crmReports();return crmDashboard()}
function crmDashboard(){return head('CRM workspace','Enrollment and relationship pipeline','Move prospective learners and schools from inquiry to activation, subscription and ongoing support.',`<button class="btn" data-action="import-leads">Import</button><button class="btn primary" data-action="new-lead">Add lead</button>`)+`<div class="kpis"><div class="kpi"><strong>326</strong><span>Open leads</span></div><div class="kpi"><strong>41%</strong><span>Trial-to-paid conversion</span></div><div class="kpi"><strong>18</strong><span>School opportunities</span></div><div class="kpi"><strong>23</strong><span>Open support cases</span></div></div><div class="section"><div class="funnel">${[['New inquiry',['Asha K.','Musa J.']],['Qualified',['Mlimani School','Neema R.']],['Trial',['Baraka J.','St. Mary Sec.']],['Payment',['Zawadi M.']],['Active',['Amani K.','Kibaha School']]].map(c=>`<div class="funnel-col"><strong>${c[0]}</strong><span class="badge neutral" style="float:right">${c[1].length}</span>${c[1].map(n=>`<div class="lead" data-action="open-lead"><strong>${n}</strong><div class="muted" style="font-size:11px">Follow-up due</div></div>`).join('')}</div>`).join('')}</div></div>`}
function crmLeads(){return head('CRM','Leads','Prospective learners, parents and school contacts with next-action tracking.',`<button class="btn primary" data-action="new-lead">Add lead</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Interest</th><th>Stage</th><th>Next action</th><th></th></tr></thead><tbody>${[['Asha K.','Parent','Form 1 annual','Qualified','Call today'],['Musa J.','Learner','Form 4 monthly','Trial','WhatsApp tomorrow'],['Mlimani School','School','240 learners','Proposal','Demo Friday']].map(x=>`<tr>${x.map(v=>`<td>${v}</td>`).join('')}<td><button class="btn sm" data-action="open-lead">Open</button></td></tr>`).join('')}</tbody></table></div>`}
function crmSchools(){return head('B2B','Schools','Manage school accounts, seats, administrators, adoption and renewal readiness.',`<button class="btn primary" data-action="new-school">Add school</button>`)+`<div class="grid">${[['Kibaha Secondary','320 seats','78% active'],['Mlimani Secondary','240 seats','Pilot'],['St. Mary Secondary','180 seats','Proposal']].map(x=>`<div class="card"><span class="badge">${x[1]}</span><h3 style="margin-top:10px">${x[0]}</h3><p>${x[2]}</p><button class="btn sm" style="margin-top:12px">Open account</button></div>`).join('')}</div>`}
function crmCampaigns(){return head('Growth','Campaigns','Track targeted enrollment and retention campaigns without turning the learning experience into an advertising feed.',`<button class="btn primary" data-action="new-campaign">Create campaign</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>Campaign</th><th>Audience</th><th>Sent</th><th>Conversion</th><th>Status</th></tr></thead><tbody><tr><td>Form 1 Back-to-School</td><td>New parents</td><td>4,120</td><td>8.4%</td><td><span class="badge ok">Active</span></td></tr><tr><td>Mock Exam Readiness</td><td>Form 4 learners</td><td>2,340</td><td>11.2%</td><td><span class="badge ok">Active</span></td></tr></tbody></table></div>`}
function crmSupport(){return head('Customer success','Support cases','Resolve access, billing and learning-support issues with clear ownership and SLA status.',`<button class="btn primary" data-action="new-case">Create case</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>Case</th><th>Learner</th><th>Category</th><th>Priority</th><th>Age</th><th></th></tr></thead><tbody><tr><td>#SUP-1042</td><td>Neema R.</td><td>Payment</td><td><span class="badge bad">High</span></td><td>6h</td><td><button class="btn sm">Open</button></td></tr><tr><td>#SUP-1041</td><td>Baraka J.</td><td>Lesson access</td><td><span class="badge warn">Medium</span></td><td>11h</td><td><button class="btn sm">Open</button></td></tr></tbody></table></div>`}
function crmReports(){return head('CRM analytics','Reports','Enrollment, conversion, subscription, school adoption and support performance.')+`<div class="kpis"><div class="kpi"><strong>41%</strong><span>Trial to paid</span></div><div class="kpi"><strong>19 days</strong><span>School sales cycle</span></div><div class="kpi"><strong>92%</strong><span>Cases within SLA</span></div><div class="kpi"><strong>81%</strong><span>Renewal intent</span></div></div>`}
function roleName(r){return {learner:'Learner',tutor:'Tutor',admin:'Super Admin',crm:'CRM'}[r]}
function icon(x){return {dashboard:'⌂',subjects:'▦',path:'→',lesson:'▤',assessments:'✓',progress:'◔',rafiki:'✦',announcements:'◉',subscription:'¤',classes:'👥',content:'▣',live:'●','learner-insights':'◫','question-bank':'?',curriculum:'⌘',users:'👤',subscriptions:'¤','content-governance':'✓',analytics:'◔',settings:'⚙',leads:'◎',schools:'▥',campaigns:'⌁',support:'?',reports:'▤'}[x]||'•'}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{const p=el.dataset.nav;if(p==='landing'){state.page='landing'}else{state.page=p}save();app()});document.querySelectorAll('[data-subject]').forEach(el=>el.onclick=()=>{state.subject=el.dataset.subject;state.page='course';save();app()});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{state.topic=+el.dataset.topic;state.page='lesson';save();app()});document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{state.lessonMode=el.dataset.mode;app()});document.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>{const [q,a]=el.dataset.answer.split(':').map(Number);state.quizAnswers[q]=a;app()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el));const gs=document.querySelector('#globalSearch');if(gs)gs.onkeydown=e=>{if(e.key==='Enter'){toast(`Search ready for “${gs.value}” — showing curriculum matches in this prototype.`);state.page=state.role==='learner'?'subjects':state.role==='admin'?'curriculum':'dashboard';app()}};}
function action(a,el){if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';save();app();return}if(a==='menu'){document.querySelector('#sidebar')?.classList.toggle('open');return}if(a==='roles'||a==='role-demo'){modal('Switch workspace','Choose a role to preview the linked platform workflow.',`<div class="grid2e">${['learner','tutor','admin','crm'].map(r=>`<button class="btn" data-role="${r}">${roleName(r)}</button>`).join('')}</div>`,`<button class="btn" data-action="close-modal">Close</button>`);setTimeout(()=>document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.role=b.dataset.role;state.page='dashboard';closeModal();save();app()}));return}if(a==='enter'){state.role='learner';state.page='dashboard';save();app();return}if(a==='close-modal'){closeModal();return}if(a==='submit-quiz'){const correct=[0,1,2];let score=correct.filter((v,i)=>state.quizAnswers[i]===v).length;state.progress.BIO=Math.max(state.progress.BIO,58+score*6);save();modal('Practice result',`${score}/3 correct`, `<div class="card"><h3>${score===3?'Competency evidence strengthened':'Use feedback, then retry'}</h3><p>${score===3?'You demonstrated this concept in guided practice. Next, complete the independent mastery checkpoint.':'Review the reflex pathway, especially the sequence and reason for speed.'}</p><div class="progress" style="margin-top:14px"><span style="width:${Math.round(score/3*100)}%"></span></div></div>`,`<button class="btn primary" data-action="close-modal">Continue</button>`);return}if(a==='rafiki-send'){const r=document.querySelector('#rafikiReply');if(r){r.style.display='block';r.innerHTML='<strong>Rafiki:</strong> A reflex is faster because the protective response can be coordinated through the spinal cord before conscious processing. Try this: 1) What detects the stimulus? 2) Which neurone carries the impulse to the spinal cord? 3) Why does the pathway reduce reaction time?';}return}if(a==='change-plan'||a==='choose-plan'||a==='create-plan'){modal('Subscription action','Plan configuration',`<div class="form-grid"><div class="field full"><label>Plan</label><select><option>Monthly Learner</option><option>Annual Learner</option><option>School Annual</option></select></div><div class="field"><label>Billing cycle</label><select><option>Monthly</option><option>Annual</option></select></div><div class="field"><label>Price (TZS)</label><input value="120000"></div><div class="field full"><label>Entitlements</label><textarea rows="5">Interactive lessons\nVideo lessons\nAudio lessons\nPDF notes\nShorts\nRafiki AI allowance</textarea></div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="modal-save">Save</button>`);return}if(['new-content','edit-content','add-curriculum','edit-curriculum'].includes(a)){modal('Curriculum resource editor','Outcome-aligned authoring',`<div class="form-grid"><div class="field"><label>Subject</label><select><option>Biology</option></select></div><div class="field"><label>Form</label><select><option>Form 3</option></select></div><div class="field full"><label>Topic / sub-topic</label><input value="Coordination / Reflex action"></div><div class="field full"><label>Learning outcome</label><textarea rows="3">Explain the pathway of a reflex arc and relate each structure to a rapid protective response.</textarea></div><div class="field"><label>Resource type</label><select><option>Interactive text</option><option>Video</option><option>Audio</option><option>PDF notes</option><option>Shorts</option><option>Live lesson</option></select></div><div class="field"><label>Status</label><select><option>Draft</option><option>Review</option><option>Published</option></select></div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="modal-save">Save resource</button>`);return}if(a==='new-assessment'||a==='generate-questions'){modal(a==='generate-questions'?'Rafiki AI question generator':'Create assessment','Outcome-mapped assessment builder',`<div class="form-grid"><div class="field"><label>Form</label><select><option>Form 3</option></select></div><div class="field"><label>Subject</label><select><option>Biology</option></select></div><div class="field"><label>Topic</label><select><option>Coordination</option></select></div><div class="field"><label>Type</label><select><option>Quiz</option><option>Assignment</option><option>Topic test</option><option>Exam</option></select></div><div class="field"><label>Questions</label><input value="10"></div><div class="field"><label>Difficulty</label><select><option>Mixed</option></select></div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="modal-generate">Generate draft</button>`);return}if(a==='new-announcement'){modal('Create announcement','Targeted in-app communication',`<div class="form-grid"><div class="field"><label>Audience</label><select><option>All learners</option><option>Form 3</option><option>Tutors</option><option>Paid learners</option></select></div><div class="field"><label>Priority</label><select><option>Academic</option><option>Operational</option><option>Urgent</option></select></div><div class="field full"><label>Title</label><input placeholder="Announcement title"></div><div class="field full"><label>Message</label><textarea rows="5" placeholder="Write a concise, actionable message"></textarea></div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="modal-save">Publish</button>`);return}if(a==='new-lead'||a==='new-school'||a==='new-case'||a==='new-campaign'){modal('Create record','CRM workflow',`<div class="form-grid"><div class="field full"><label>Name / title</label><input placeholder="Enter name"></div><div class="field"><label>Type</label><select><option>Learner</option><option>Parent</option><option>School</option></select></div><div class="field"><label>Stage / priority</label><select><option>New</option><option>Qualified</option><option>High</option></select></div><div class="field full"><label>Next action</label><textarea rows="3"></textarea></div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="modal-save">Save</button>`);return}if(a==='modal-save'||a==='modal-generate'){closeModal();toast(a==='modal-generate'?'Draft generated and added to review queue.':'Saved successfully.');return}toast(labelAction(a))}
function labelAction(a){return {'play':'Playback toggled','short-next':'Next short opened','save-note':'Note saved to learner notebook','mark-read':'Announcement marked read','mark-all':'All announcements marked read','billing':'Billing history opened','assessment-history':'Assessment history opened','create-class':'Class creation opened','open-class':'Class workspace opened','import-content':'Import workflow opened','schedule-live':'Live lesson scheduler opened','start-live':'Live room started','assign-intervention':'Intervention assigned','import-questions':'Question import opened','review-question':'Question review opened','export-curriculum':'Curriculum export prepared','invite-user':'Invitation workflow opened','create-user':'User creation opened','edit-user':'User management opened','export-subscriptions':'Subscription report prepared','review-queue':'Review queue opened','save-settings':'Platform settings saved','import-leads':'Lead import opened','open-lead':'Lead detail opened','mic':'Microphone toggled','hand':'Hand raised','leave-live':'You left the live lesson','rafiki-history':'Rafiki study history opened'}[a]||'Action completed'}
function modal(title,eyebrow,body,foot=''){document.querySelector('#modalTitle').textContent=title;document.querySelector('#modalEyebrow').textContent=eyebrow;document.querySelector('#modalBody').innerHTML=body;document.querySelector('#modalFoot').innerHTML=foot;document.querySelector('#modal').classList.add('open');document.querySelector('#modal').setAttribute('aria-hidden','false');setTimeout(()=>document.querySelectorAll('#modal [data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el)),0)}
function closeModal(){document.querySelector('#modal').classList.remove('open');document.querySelector('#modal').setAttribute('aria-hidden','true')}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._tt);window._tt=setTimeout(()=>t.classList.remove('show'),2200)}
if(state.page==='course'&&state.role!=='learner')state.page='dashboard';app();
